/**
 * Which PvP trinket a unit's slots hold. Its own module so that the kill-tier
 * files can ask without importing `ccTrinketAnalysis`, which imports them.
 */
import type { ICombatUnit } from "@gladlog/parser-compat";

import trinketItemIdsData from "../data/trinketItemIds.json";
import { MEDALLION_SPELL_ID } from "./pvpTrinketUses";

/** Item IDs for Relentless (passive DR, no active) — generated by start:generateTrinketItemIds */
const RELENTLESS_ITEM_IDS = new Set<string>(
  trinketItemIdsData.relentlessItemIds,
);
/** Item IDs for Adaptation (auto-break on 5s CC, no manual cast) — generated by start:generateTrinketItemIds */
const ADAPTATION_ITEM_IDS = new Set<string>(
  trinketItemIdsData.adaptationItemIds,
);
/** Item IDs whose on-use is Gladiator's Medallion (ItemEffect.SpellID 336126),
 * generated by the same script. Reliability round 3 W1j: every trinket that was
 * not Adaptation / Relentless used to count as a Medallion, so a player with
 * two non-PvP trinkets was "PvP Trinket available" (0e0663e6). On a 303-file
 * sample every one of 2,719 Medallion casters held one of these items; 79 of
 * 3,831 players the old rule called "Gladiator" held none and never cast. */
const GLADIATOR_ITEM_IDS = new Set<string>(trinketItemIdsData.gladiatorItemIds);

/** "None" = equipment is known and holds no PvP trinket (no Medallion item and
 * no Medallion cast); "Unknown" = no equipment to read. */
export type TrinketType =
  "Gladiator" | "Adaptation" | "Relentless" | "None" | "Unknown";

export function detectTrinketType(unit: ICombatUnit): TrinketType {
  const trinketSlots = (unit.info?.equipment ?? []).filter((_, i) =>
    [12, 13].includes(i),
  );
  if (trinketSlots.some((e) => RELENTLESS_ITEM_IDS.has(e.id)))
    return "Relentless";
  if (trinketSlots.some((e) => ADAPTATION_ITEM_IDS.has(e.id)))
    return "Adaptation";
  if (
    trinketSlots.some((e) => GLADIATOR_ITEM_IDS.has(e.id)) ||
    (unit.spellCastEvents ?? []).some((e) => e.spellId === MEDALLION_SPELL_ID)
  )
    return "Gladiator";
  if (trinketSlots.length > 0) return "None";
  return "Unknown";
}

/**
 * Does the unit hold a PvP trinket it can press — the `null` of
 * `pvpTrinketRemainingSecondsAt`, read off the unit alone: Relentless is
 * passive, "None" holds two other trinkets (user ruling 2026-10-31, fact7 r5:
 * 705 of 17,232 `trinket up` lines on the 605, 36 units, 247 with no break
 * racial seen). The kill tier still treats such a unit as `locked` — P-b7's
 * tier is not this fact — and only what the line says changes.
 */
export function hasPressablePvpTrinket(unit: ICombatUnit): boolean {
  const type = detectTrinketType(unit);
  return type !== "Relentless" && type !== "None";
}
